import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.11','Schalten und Erden von Fahrleitungen, Ziff.')
add("1.1","Geltungsbereich","Welche Aspekte des Eisenbahnbetriebs betreffen die Vorschriften gemäss §?","Die Aspekte in Zusammenhang mit Fahrleitungen.",["Die Aspekte in Zusammenhang mit Rangierbewegungen.","Die Aspekte in Zusammenhang mit Zugbeeinflussung.","Die Aspekte in Zusammenhang mit Arbeitssicherheit allgemein."],"Diese Vorschriften betreffen die Aspekte des Eisenbahnbetriebs in Zusammenhang mit Fahrleitungen.")
F="Zum Erteilen von Schaltbefehlen zum Ein- und Ausschalten berechtigt sind: von EBU bezeichnete SPEA, IPEA. Zum Erteilen von Ausschaltbefehlen berechtigt sind: weiteres vom EBU bezeichnetes Personal, Dritte im Notfall."
addm("2.1.1","Ein- und Ausschalten","Wer ist gemäss § zum Erteilen von Schaltbefehlen zum Ein- und Ausschalten berechtigt (Mehrfachauswahl).",["Von EBU bezeichnete SPEA","IPEA"],["Jeder LF","Der FDL ohne Bezeichnung","Dritte im Notfall"],F)
addm("2.1.1","Nur Ausschalten","Wer ist gemäss § nur zum Erteilen von Ausschaltbefehlen berechtigt (Mehrfachauswahl).",["Weiteres vom EBU bezeichnetes Personal","Dritte im Notfall"],["Von EBU bezeichnete SPEA","IPEA","Jeder RL"],F)
F="Schaltbefehle müssen eindeutig und unmissverständlich sein. Schaltbefehle werden mindestens mit folgenden Angaben erteilt: Name und Funktionsbezeichnung; Ort (Bahnhof, Spurwechsel, Gleisnummer, betroffener Abschnitt, usw.); Bezeichnung des Schalters; Passwort, in den von der ISB vorgeschriebenen Fällen. Das Passwort wird durch die den Schaltbefehl ausführende Stelle zugeteilt. Aufträge zum Wiedereinschalten des betreffenden Schaltabschnittes werden nur ausgeführt, wenn sie vom gleichen Passwort begleitet sind. Personen, die nur zum Erteilen von Ausschaltbefehlen berechtigt sind, bezeichnen die auszuschaltenden Gleise oder Leitungen möglichst präzise. Im Notfall oder Zweifelsfall wird grossräumig ausgeschaltet. Schaltbefehle und die Bestätigung der Ausführung einer Schaltung werden protokollpflichtig übermittelt. Für Gleise, welche normalerweise ausgeschaltet sind, dürfen Schaltbefehle und die Bestätigung der Ausführung der Schaltung quittungspflichtig übermittelt werden."
add("2.1.2","Anforderung Schaltbefehle","Wie müssen Schaltbefehle gemäss § sein?","Eindeutig und unmissverständlich.",["Mündlich und kurz.","Nur schriftlich.","Nur mit Passwort."],F)
addm("2.1.2","Mindestangaben","Welche Angaben enthalten Schaltbefehle gemäss § mindestens (Mehrfachauswahl).",["Name und Funktionsbezeichnung","Ort (Bahnhof, Spurwechsel, Gleisnummer, betroffener Abschnitt usw.)","Bezeichnung des Schalters","Passwort, in den von der ISB vorgeschriebenen Fällen"],["Zugnummer des nächsten Zuges","Uhrzeit der nächsten Zugfahrt"],F)
add("2.1.2","Passwort Zuteilung","Wer teilt das Passwort gemäss § zu?","Die den Schaltbefehl ausführende Stelle.",["Der Auftraggeber.","Die ISB.","Der FDL."],F)
add("2.1.2","Passwort Wiedereinschalten","Wann werden Aufträge zum Wiedereinschalten des Schaltabschnittes gemäss § ausgeführt?","Nur wenn sie vom gleichen Passwort begleitet sind.",["Wenn sie vom FDL bestätigt sind.","Wenn die Fahrzeit abgelaufen ist.","Immer, ohne Passwort."],F)
add("2.1.2","Nur Ausschaltbefugte","Wie bezeichnen Personen, die nur zum Erteilen von Ausschaltbefehlen berechtigt sind, gemäss § die auszuschaltenden Gleise oder Leitungen?","Möglichst präzise.",["Grossräumig.","Nur mit Gleisnummer.","Nur mit Kilometerangabe."],F)
add("2.1.2","Notfall ausschalten","Wie wird im Notfall oder Zweifelsfall gemäss § ausgeschaltet?","Grossräumig.",["Möglichst präzise auf das Gleis beschränkt.","Nur im betroffenen Gleis.","Erst nach Rückfrage beim FDL."],F)
add("2.1.2","Übermittlung Schaltbefehle","Wie werden Schaltbefehle und die Bestätigung der Ausführung gemäss § grundsätzlich übermittelt?","Protokollpflichtig.",["Quittungspflichtig.","Mündlich ohne Quittung.","Mit Zirkular."],F)
add("2.1.2","Übermittlung normalerweise ausgeschaltet","Wie dürfen Schaltbefehle für Gleise, welche normalerweise ausgeschaltet sind, gemäss § übermittelt werden?","Quittungspflichtig.",["Protokollpflichtig mit Passwort.","Mündlich ohne Quittung.","Nur per Zirkular."],F)
F="Schaltungen an ferngesteuerten Schaltern werden grundsätzlich von den entsprechenden Fernsteuerzentren ausgeführt. Schaltungen an örtlich bedienten Strecken- oder Bahnhofschaltern von Bahnhofsektoren oder Unterhalts- und Serviceanlagen werden durch SPEA oder IPEA bzw. im Auftrag des zuständigen Dienstes durch die vom EBU bezeichneten IPEA ausgeführt."
add("2.1.3","Ferngesteuerte Schalter","Von wem werden Schaltungen an ferngesteuerten Schaltern gemäss § grundsätzlich ausgeführt?","Von den entsprechenden Fernsteuerzentren.",["Von der IPEA vor Ort.","Vom FDL.","Vom LF."],F)
add("2.1.3","Örtlich bediente Schalter","Von wem werden Schaltungen an örtlich bedienten Strecken- oder Bahnhofschaltern gemäss § ausgeführt?","Durch SPEA oder IPEA bzw. im Auftrag des zuständigen Dienstes durch die vom EBU bezeichneten IPEA.",["Durch die Fernsteuerzentren.","Durch den FDL.","Durch jeden Mitarbeitenden des EBU."],F)
F="Ausschalten von Fahrleitungen im Bahnbetrieb: Der FDL hat die verlangte Ausschaltung an der Sicherungsanlage zu sichern. Die schaltberechtigte Person, welche die Schaltung ausführt, hat den Schalter gegen unbeabsichtigtes Wiedereinschalten zu sichern. Die Sicherung hat vor der Übermittlung der Bestätigung an den Auftraggeber zu erfolgen. Einschalten von Fahrleitungen im Bahnbetrieb: Die schaltberechtigte Person hebt die gegen unbeabsichtigtes Wiedereinschalten getroffene Sicherungsmassnahme auf, führt die Schaltung aus und bestätigt diese anschliessend dem Auftraggeber. Nach dem Einschalten hebt der FDL die damit verbundenen Sicherungsmassnahmen auf."
add("2.1.4","FDL Ausschaltung sichern","Was hat der FDL gemäss § bei einer verlangten Ausschaltung der Fahrleitung zu tun?","Die verlangte Ausschaltung an der Sicherungsanlage sichern.",["Den Schalter selbst gegen Wiedereinschalten sichern.","Die Fahrleitung erden.","Die Ausschaltung dem LF melden."],F)
add("2.1.4","Schalter sichern","Wer sichert gemäss § den Schalter gegen unbeabsichtigtes Wiedereinschalten?","Die schaltberechtigte Person, welche die Schaltung ausführt.",["Der FDL.","Der Auftraggeber.","Das Fernsteuerzentrum."],F)
add("2.1.4","Zeitpunkt Sicherung","Wann hat die Sicherung des Schalters gegen Wiedereinschalten gemäss § zu erfolgen?","Vor der Übermittlung der Bestätigung an den Auftraggeber.",["Nach der Übermittlung der Bestätigung.","Nach Abschluss der Arbeiten.","Beim nächsten Schichtwechsel."],F)
addm("2.1.4","Einschalten Ablauf","Wie läuft das Einschalten von Fahrleitungen im Bahnbetrieb gemäss § ab (Mehrfachauswahl).",["Die schaltberechtigte Person hebt die Sicherungsmassnahme gegen Wiedereinschalten auf","Die schaltberechtigte Person führt die Schaltung aus","Die schaltberechtigte Person bestätigt die Schaltung anschliessend dem Auftraggeber","Nach dem Einschalten hebt der FDL die damit verbundenen Sicherungsmassnahmen auf"],["Der FDL führt die Schaltung selbst aus","Der LF hebt die Sicherung nach dem Einschalten auf"],F)
add("2.1.4","FDL nach Einschalten","Was hat der FDL gemäss § nach dem Einschalten der Fahrleitung zu tun?","Die damit verbundenen Sicherungsmassnahmen aufheben.",["Den Schalter sichern.","Die Fahrleitung erden.","Das Passwort neu zuteilen."],F)
F="Hörnerschalter dürfen nur ausgeschaltet werden, sofern sichergestellt ist, dass die unter den entsprechenden Fahrleitungen stehenden Fahrzeuge die Stromabnehmer gesenkt haben und allfällige andere an diesem Hörnerschalter bzw. an der Fahrleitung angeschlossene Verbraucher (z.B. Zugvorheiz- und Weichenheizanlagen) ausgeschaltet sind."
addm("2.1.5","Hörnerschalter","Was muss gemäss § sichergestellt sein, bevor Hörnerschalter ausgeschaltet werden dürfen (Mehrfachauswahl).",["Die unter den Fahrleitungen stehenden Fahrzeuge haben die Stromabnehmer gesenkt","Andere angeschlossene Verbraucher (z.B. Zugvorheiz- und Weichenheizanlagen) sind ausgeschaltet"],["Die Fahrleitung ist geerdet","Der FDL hat die Schaltung quittiert","Alle Weichen sind verschlossen"],F)
add("2.2.1","Erdungsberechtigung SPEA","Wo sind SPEA gemäss § zum Erden von Fahrleitungen berechtigt?","In allen Eisenbahnanlagen.",["Nur in Anlagen, für die sie eine konkrete Instruktion erhalten haben.","Nur in Bahnhöfen.","Nur in Verladegleisen."],"Zum Erden von Fahrleitungen berechtigt sind SPEA in allen Eisenbahnanlagen sowie IPEA in jenen Anlagen, für die sie die konkrete Instruktion erhalten haben.")
add("2.2.1","Erdungsberechtigung IPEA","Wo sind IPEA gemäss § zum Erden von Fahrleitungen berechtigt?","In jenen Anlagen, für die sie die konkrete Instruktion erhalten haben.",["In allen Eisenbahnanlagen.","Nur in Verladegleisen.","Nirgends, nur SPEA dürfen erden."],"Zum Erden von Fahrleitungen berechtigt sind SPEA in allen Eisenbahnanlagen sowie IPEA in jenen Anlagen, für die sie die konkrete Instruktion erhalten haben.")
add("2.2.2","Defekte Erdungsvorrichtungen","Was gilt gemäss § für defekte oder ungeprüfte Erdungsvorrichtungen und Spannungsprüfer?","Sie dürfen nicht verwendet werden und sind dem zuständigen Dienst zu melden.",["Sie dürfen mit besonderer Vorsicht verwendet werden.","Sie dürfen nur von SPEA verwendet werden.","Sie sind bei der nächsten Revision zu melden."],"Defekte oder ungeprüfte Erdungsvorrichtungen und Spannungsprüfer dürfen nicht verwendet werden und sind dem zuständigen Dienst zu melden.")
F="Fahrleitungen in Verladegleisen sind aus Sicherheitsgründen auszuschalten und zu erden. Ausnahmen von dieser Regelung dürfen von der ISB nur bewilligt werden, wenn sie zwingend nötig sind und die Sicherheitsabstände gemäss der Eisenbahngesetzgebung für alle in den Anlagevorschriften vorgesehenen Betriebszustände gewährleistet sind. Bei Rampen-, Schuppen- oder Freiverladegleisen, welche normalerweise ausgeschaltet sind, sind die Fahrleitungen erst einzuschalten, bevor ein elektrisches Triebfahrzeug in die betreffenden Gleise einfahren muss. Sobald das Triebfahrzeug ausgefahren ist, sind die Fahrleitungen wieder auszuschalten und zu erden."
add("2.3.1","Verladegleise Grundsatz","Wie sind Fahrleitungen in Verladegleisen gemäss § aus Sicherheitsgründen zu halten?","Ausgeschaltet und geerdet.",["Eingeschaltet und geerdet.","Ausgeschaltet, aber nicht geerdet.","Eingeschaltet mit gesenkten Stromabnehmern."],F)
addm("2.3.1","Ausnahmen Verladegleise","Unter welchen Bedingungen darf die ISB Ausnahmen von der Regelung für Verladegleise gemäss § bewilligen (Mehrfachauswahl).",["Die Ausnahme ist zwingend nötig","Die Sicherheitsabstände gemäss Eisenbahngesetzgebung sind für alle vorgesehenen Betriebszustände gewährleistet"],["Der Kunde stimmt zu","Der FDL bestätigt die Ausnahme quittungspflichtig"],F)
add("2.3.1","Rampengleise einschalten","Wann sind die Fahrleitungen bei normalerweise ausgeschalteten Rampen-, Schuppen- oder Freiverladegleisen gemäss § einzuschalten?","Erst bevor ein elektrisches Triebfahrzeug in die betreffenden Gleise einfahren muss.",["Dauernd während der Verladearbeiten.","Am Anfang jedes Betriebstages.","Sobald der Kunde die Verladearbeiten abgeschlossen hat."],F)
add("2.3.1","Rampengleise ausschalten","Wann sind die Fahrleitungen bei Rampen-, Schuppen- oder Freiverladegleisen gemäss § wieder auszuschalten und zu erden?","Sobald das Triebfahrzeug ausgefahren ist.",["Erst am Ende des Betriebstages.","Erst nach Anweisung des Kunden.","Beim Einfahren des nächsten Triebfahrzeugs."],F)
F="Kunden, die Verlade- oder Entladearbeiten vornehmen, sind über die Gefahren des elektrischen Stroms aufmerksam zu machen. Vor der Verständigung eines Kunden über ein ausgeschaltetes Gleis, muss die Fahrleitung ausgeschaltet und geerdet werden. Muss die Fahrleitung eines Verladegleises wieder eingeschaltet werden, sind die betreffenden Kunden vor dem Einschalten darüber zu verständigen. Das EVU, welches die Fahrzeuge zum Beladen oder Entladen bereitstellt bzw. nach den Verladearbeiten abholt, ist für die Information ihrer Kunden verantwortlich."
add("2.3.2","Kunden aufmerksam machen","Worüber sind Kunden, die Verlade- oder Entladearbeiten vornehmen, gemäss § aufmerksam zu machen?","Über die Gefahren des elektrischen Stroms.",["Über die Fahrzeiten der Züge.","Über die Tarife.","Über die Gefahren von Gefahrgut."],F)
add("2.3.2","Verständigung ausgeschaltetes Gleis","Was muss gemäss § vor der Verständigung eines Kunden über ein ausgeschaltetes Gleis geschehen sein?","Die Fahrleitung muss ausgeschaltet und geerdet sein.",["Die Fahrleitung muss nur ausgeschaltet sein.","Der FDL muss das Gleis gesperrt haben.","Die Stromabnehmer müssen gesenkt sein."],F)
add("2.3.2","Wiedereinschalten Kunden","Wann sind die Kunden gemäss § zu verständigen, wenn die Fahrleitung eines Verladegleises wieder eingeschaltet werden muss?","Vor dem Einschalten.",["Nach dem Einschalten.","Gar nicht, wenn die Arbeiten abgeschlossen sind.","Erst nach der Einfahrt des Triebfahrzeugs."],F)
add("2.3.2","Verantwortlich Information","Wer ist gemäss § für die Information der Kunden verantwortlich?","Das EVU, welches die Fahrzeuge zum Beladen oder Entladen bereitstellt bzw. abholt.",["Die ISB.","Der FDL.","Der LF des Triebfahrzeugs."],F)
